import{_ as e,r as n,o,c,e as a,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const h=JSON.parse('{"title":"集合 - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"可用方法","slug":"可用方法","link":"#可用方法","children":[]},{"level":2,"title":"自定义集合","slug":"自定义集合","link":"#自定义集合","children":[]}],"relativePath":"3.x/zh-cn/extend/database/collection.md","filePath":"3.x/zh-cn/extend/database/collection.md"}'),i={name:"3.x/zh-cn/extend/database/collection.md"};function r(k,s,d,g,v,m){const p=n("pre-heading"),t=n("post-heading");return o(),c("div",null,[a(p),s[0]||(s[0]=l("h1",null,"集合",-1)),a(t),s[1]||(s[1]=u(`<p>模型返回的所有多结果集都是 <code>October\\Rain\\Database\\Collection</code> 对象的实例，包括通过 <code>get</code> 方法检索的结果或通过关联访问的结果。<code>Collection</code> 对象继承了<a href="./../services/collections.html">基础集合</a>，因此它自然继承了数十种用于流畅地操作底层模型数组的方法。</p><p>所有集合也充当迭代器，允许您像简单的 PHP 数组一样遍历它们。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_active&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$users</span> <span class="token keyword">as</span> <span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>但是，集合比数组强大得多，它使用直观的接口公开了各种 map / reduce 操作。例如，让我们过滤所有活跃的模型并收集每个过滤用户的名称。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$names</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">is_active</span> <span class="token operator">===</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>虽然大多数模型集合方法返回 <code>Eloquent</code> 集合的新实例，但 <code>pluck</code>、<code>keys</code>、<code>zip</code>、<code>collapse</code>、<code>flatten</code> 和 <code>flip</code> 方法返回基础集合实例。同样，如果 <code>map</code> 操作返回不包含任何模型的集合，它将自动转换为基础集合。</p></div><h2 id="可用方法"><a href="#可用方法" class="header-anchor">#</a> 可用方法</h2><p>所有模型集合都继承基础集合对象；因此，它们继承了基础集合类提供的所有强大方法。</p><p>此外，<code>October\\Rain\\Database\\Collection</code> 类提供了一个方法超集来帮助管理您的模型集合。大多数方法返回 <code>October\\Rain\\Database\\Collection</code> 实例；但是，有些方法返回基础 <code>Illuminate\\Support\\Collection</code> 实例。</p><p><strong>contains($key, $operator = null, $value = null)</strong></p><p><code>contains</code> 方法可用于确定集合中是否包含给定的模型实例。此方法接受主键或模型实例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">contains</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">contains</span><span class="token punctuation">(</span><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>diff($items)</strong></p><p><code>diff</code> 方法返回给定集合中不存在的所有模型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">App<span class="token punctuation">\\</span>User</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">diff</span><span class="token punctuation">(</span><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>except($keys)</strong></p><p><code>except</code> 方法返回没有给定主键的所有模型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">except</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>find($key)</strong></p><p><code>find</code> 方法查找具有给定主键的模型。如果 <code>$key</code> 是模型实例，<code>find</code> 将尝试返回与主键匹配的模型。如果 <code>$key</code> 是键数组，find 将使用 <code>whereIn()</code> 返回与 <code>$keys</code> 匹配的所有模型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$user</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>fresh($with = [])</strong></p><p><code>fresh</code> 方法从数据库中检索集合中每个模型的新实例。此外，任何指定的关联都将被预加载：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">fresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">fresh</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>intersect($items)</strong></p><p><code>intersect</code> 方法返回给定集合中也存在的所有模型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">App<span class="token punctuation">\\</span>User</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">intersect</span><span class="token punctuation">(</span><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>load($relations)</strong></p><p><code>load</code> 方法为集合中的所有模型预加载给定的关联：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments.author&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>loadMissing($relations)</strong></p><p><code>loadMissing</code> 方法为集合中的所有模型预加载给定的关联（如果关联尚未加载）：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">loadMissing</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">loadMissing</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments.author&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>modelKeys()</strong></p><p><code>modelKeys</code> 方法返回集合中所有模型的主键：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">modelKeys</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// [1, 2, 3, 4, 5]</span>
</code></pre></div><p><strong>makeVisible($attributes)</strong></p><p><code>makeVisible</code> 方法使集合中每个模型上通常&quot;隐藏&quot;的属性变为可见：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">makeVisible</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;address&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;phone_number&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>makeHidden($attributes)</strong></p><p><code>makeHidden</code> 方法隐藏集合中每个模型上通常&quot;可见&quot;的属性：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">makeHidden</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;address&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;phone_number&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>only($keys)</strong></p><p><code>only</code> 方法返回具有给定主键的所有模型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">only</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><strong>unique($key = null, $strict = false)</strong></p><p><code>unique</code> 方法返回集合中所有唯一的模型。与集合中另一个具有相同主键的相同类型的模型将被移除。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">unique</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="自定义集合"><a href="#自定义集合" class="header-anchor">#</a> 自定义集合</h2><p>如果您需要使用自定义 <code>Collection</code> 对象及其自己的扩展方法，您可以在模型上覆盖 <code>newCollection</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * Create a new Collection instance.
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">newCollection</span><span class="token punctuation">(</span><span class="token keyword type-hint">array</span> <span class="token variable">$models</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">CustomCollection</span><span class="token punctuation">(</span><span class="token variable">$models</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>一旦定义了 <code>newCollection</code> 方法，每当模型返回 <code>Collection</code> 实例时，您都会收到自定义集合的实例。如果您想为插件或应用程序中的每个模型使用自定义集合，您应该在所有模型继承的基础模型类上覆盖 <code>newCollection</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Collection</span> <span class="token keyword">as</span> CollectionBase<span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">CustomCollection</span> <span class="token keyword">extends</span> <span class="token class-name">CollectionBase</span>
<span class="token punctuation">{</span>
<span class="token punctuation">}</span>
</code></pre></div>`,53))])}const f=e(i,[["render",r]]);export{h as __pageData,f as default};
